{
  "findings": [
    {
      "check_id": "CKV_AWS_364",
      "title": "Ensure that AWS Lambda function permissions delegated to AWS services are limited by SourceArn or SourceAccount",
      "resource": "aws_lambda_permission.api_gateway_invoke",
      "severity": "MEDIUM",
      "explanation": "The Lambda permission allows invocation from any API Gateway without restriction by SourceArn or SourceAccount."
    },
    {
      "check_id": "AVD-AWS-0067",
      "title": "Lambda permission lacks source ARN for *.amazonaws.com principal.",
      "resource": "aws_lambda_permission.api_gateway_invoke",
      "severity": "CRITICAL",
      "explanation": "Not providing the source ARN allows any resource from the principal, even from other accounts, to invoke the Lambda function."
    }
  ],
  "patched_code": "resource \"aws_lambda_permission\" \"api_gateway_invoke\" {\n  statement_id  = \"AllowExecutionFromAPIGateway\"\n  action        = \"lambda:InvokeFunction\"\n  function_name = aws_lambda_function.log_processing_pipeline.function_name\n  principal     = \"apigateway.amazonaws.com\"\n  source_arn = \"${aws_api_gateway_rest_api.log_processing_pipeline.execution_arn}/*/*\"\n}",
  "fix_summary": "Added source_arn to aws_lambda_permission to restrict invocation to a specific API Gateway ARN, remediating both CKV_AWS_364 and AVD-AWS-0067 findings."
}
